 76→    class Coordinator: NSObject, WKUIDelegate, WKNavigationDelegate, AVPictureInPictureControllerDelegate {
 77→        private weak var viewModelContext: CallScreenViewModel.Context?
 78→        private let certificateValidator: CertificateValidatorHookProtocol
