 90→        init(viewModelContext: CallScreenViewModel.Context) {
 91→            self.viewModelContext = viewModelContext
 92→            certificateValidator = viewModelContext.viewState.certificateValidator
 93→            pictureInPictureViewController = AVPictureInPictureVideoCallViewController()
 94→            pictureInPictureViewController.preferredContentSize = CGSize(width: 1920, height: 1080)
 95→            
 96→            super.init()
 97→            
 98→            DispatchQueue.main.async { // Avoid `Publishing changes from within view update` warnings
 99→                viewModelContext.javaScriptEvaluator = self.evaluateJavaScript
100→                viewModelContext.requestPictureInPictureHandler = self.requestPictureInPicture
101→            }
102→            
103→            let configuration = WKWebViewConfiguration()
104→            
105→            let userContentController = WKUserContentController()
106→            CallScreenJavaScriptMessageName.allCases.forEach {
107→                userContentController.add(WKScriptMessageHandlerWrapper(self), name: $0.rawValue)
108→            }
109→            
110→            // Required to allow a webview that uses file URL to load its own assets
111→            configuration.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
112→            configuration.userContentController = userContentController
113→            configuration.allowsInlineMediaPlayback = true
114→            configuration.allowsPictureInPictureMediaPlayback = true
115→            
116→            if let script = viewModelContext.viewState.script {
117→                let userScript = WKUserScript(source: script, injectionTime: .atDocumentEnd, forMainFrameOnly: false)
118→                configuration.userContentController.addUserScript(userScript)
119→            }
120→            
121→            webView = WKWebView(frame: .zero, configuration: configuration)
122→            webView.uiDelegate = self
123→            webView.navigationDelegate = self
124→            webView.isInspectable = true
125→            
126→            // https://stackoverflow.com/a/77963877/730924
127→            webView.allowsLinkPreview = true
128→            
129→            // Try matching Element Call colors
130→            webView.isOpaque = false
131→            webView.backgroundColor = .compound.bgCanvasDefault
132→            webView.scrollView.backgroundColor = .compound.bgCanvasDefault
133→            
134→            // This button is always hidden and is only used to be programmaticaly tapped
135→            routePickerView = AVRoutePickerView(frame: .zero)
136→            routePickerView.isHidden = true
137→            routePickerView.isUserInteractionEnabled = false
138→            webView.addSubview(routePickerView)
139→            
140→            webViewWrapper.addMatchedSubview(webView)
141→            
142→            if AVPictureInPictureController.isPictureInPictureSupported() {
143→                let pictureInPictureController = AVPictureInPictureController(contentSource: .init(activeVideoCallSourceView: webViewWrapper,
144→                                                                                                   contentViewController: pictureInPictureViewController))
145→                pictureInPictureController.delegate = self
146→                self.pictureInPictureController = pictureInPictureController
147→                viewModelContext.send(viewAction: .pictureInPictureIsAvailable(pictureInPictureController))
148→            }
