151→        func load(_ url: URL) {
152→            self.url = url
153→            // The only file URL we allow is the one coming from our own local ElementCall bundle, so it's okay to allow read permission only to our local EC bundle
154→            if url.isFileURL {
155→                webView.loadFileURL(url, allowingReadAccessTo: EmbeddedElementCall.bundle.bundleURL)
156→            } else {
157→                let request = URLRequest(url: url)
158→                webView.load(request)
159→            }
160→        }
161→        
162→        func evaluateJavaScript(_ script: String) async throws -> Any? {
163→            // After testing different scenarios it seems that when using async/await version of these
164→            // methods wkwebView expects JavaScript to return with a value (something other than Void),
165→            // if there is no value returning from the JavaScript that you evaluate you will have a crash.
166→            try await withCheckedThrowingContinuation { [weak self] continuaton in
167→                self?.webView.evaluateJavaScript(script) { result, error in
168→                    if let error {
169→                        continuaton.resume(throwing: error)
170→                    } else {
171→                        continuaton.resume(returning: result)
172→                    }
173→                }
174→            }
175→        }
