177→        func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
178→            guard let handlerID = CallScreenJavaScriptMessageName(rawValue: message.name) else {
179→                return
180→            }
181→            
182→            switch handlerID {
183→            case .widgetAction:
184→                guard let message = message.body as? String else { return }
185→                viewModelContext?.send(viewAction: .widgetAction(message: message))
186→            case .showNativeOutputDevicePicker:
187→                DispatchQueue.main.async {
188→                    self.tapRoutePickerView()
189→                }
190→            case .onOutputDeviceSelect:
191→                guard let deviceID = message.body as? String else { return }
192→                viewModelContext?.send(viewAction: .outputDeviceSelected(deviceID: deviceID))
193→            case .onBackButtonPressed:
194→                viewModelContext?.send(viewAction: .navigateBack)
195→            }
196→        }
