210→        func webView(_ webView: WKWebView, decideMediaCapturePermissionsFor origin: WKSecurityOrigin, initiatedBy frame: WKFrameInfo, type: WKMediaCaptureType) async -> WKPermissionDecision {
211→            // Allow if the origin is local, otherwise don't allow permissions for domains different than what the call was started on
212→            guard origin.protocol == "file" || origin.host == url.host else {
213→                return .deny
214→            }
215→            
216→            viewModelContext?.send(viewAction: .mediaCapturePermissionGranted)
217→            return .grant
218→        }
