226→        func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction) async -> WKNavigationActionPolicy {
227→            if let navigationURL = navigationAction.request.url {
228→                // Do not allow navigation to a different URL scheme.
229→                if navigationURL.scheme != url.scheme {
230→                    return .cancel
231→                }
232→                
233→                // Allow any content from the main URL.
234→                if navigationURL.host == url.host {
235→                    return .allow
236→                }
237→            }
238→            
239→            // Additionally allow any embedded content such as captchas.
240→            if let targetFrame = navigationAction.targetFrame, !targetFrame.isMainFrame {
241→                return .allow
242→            }
243→            
244→            // Otherwise the request is invalid.
245→            return .cancel
246→        }
