300→        /// Whether the web view can do picture in picture or not (e.g. it is showing an error or the page didn't load).
301→        private func webViewCanEnterPictureInPicture() async -> Result<Bool, CallScreenError> {
302→            do {
303→                guard let canEnterPictureInPicture = try await evaluateJavaScript("controls.canEnterPip()") as? Bool else {
304→                    MXLog.error("canEnterPip returned an unexpected value, skipping picture in picture.")
305→                    return .failure(.pictureInPictureNotAvailable)
306→                }
307→                MXLog.info("canEnterPip returned \(canEnterPictureInPicture)")
308→                return .success(canEnterPictureInPicture)
309→            } catch {
310→                MXLog.error("Error checking canEnterPip: \(error)")
311→                return .failure(.pictureInPictureNotAvailable)
312→            }
313→        }
