 51→/// Identifies each event handler used by the CallScreen webview
 52→///
 53→/// The names of the enum need to always match the name of the handlers on the webview.
 54→enum CallScreenJavaScriptMessageName: String, CaseIterable {
 55→    /// Widget actions's handler.
 56→    case widgetAction
 57→    /// Used to show the native AVRoutePickerView.
 58→    case showNativeOutputDevicePicker
 59→    /// Used to determine if the webview has selected the earpiece or not.
 60→    case onOutputDeviceSelect
 61→    /// Used to handle the webview back button
 62→    case onBackButtonPressed
 63→    
 64→    private var postMessageScript: String {
 65→        switch self {
 66→        case .widgetAction:
 67→            """
 68→            window.addEventListener(
 69→                "message",
 70→                (event) => {
 71→                    let message = {data: event.data, origin: event.origin};
 72→                    if (message.data.response && message.data.api == "toWidget"
 73→                    || !message.data.response && message.data.api == "fromWidget") {
 74→                        window.webkit.messageHandlers.\(rawValue).postMessage(JSON.stringify(message.data));
 75→                    } else {
 76→                        console.log("-- skipped event handling by the client because it is send from the client itself.");
 77→                    }
 78→                },
 79→                false,
 80→            );
 81→            """
 82→        case .showNativeOutputDevicePicker:
 83→            """
 84→            window.controls.\(rawValue) = () => {
 85→                window.webkit.messageHandlers.\(rawValue).postMessage("");
 86→            };
 87→            """
 88→        case .onOutputDeviceSelect:
 89→            """
 90→            window.controls.\(rawValue) = (id) => {
 91→                window.webkit.messageHandlers.\(rawValue).postMessage(id);
 92→            };
 93→            """
 94→        case .onBackButtonPressed:
 95→            """
 96→            window.controls.\(rawValue) = () => {
 97→                window.webkit.messageHandlers.\(rawValue).postMessage("");
 98→            }
 99→            """
100→        }
101→    }
102→    
103→    static var allCasesInjectionScript: String {
104→        allCases.map(\.postMessageScript).joined(separator: "\n")
105→    }
106→}
