107→    /// Find the first alias that matches the given homeserver
108→    /// - Parameters:
109→    ///   - serverName: the homserver in question
110→    ///   - useFallback: whether to return any alias if none match
111→    func firstAliasMatching(serverName: String?, useFallback: Bool) -> String? {
112→        guard let serverName else { return nil }
113→        
114→        // Check if the canonical alias matches the homeserver
115→        if let canonicalAlias,
116→           canonicalAlias.range(of: serverName) != nil {
117→            return canonicalAlias
118→        }
119→        
120→        // Otherwise check the alternative aliases and return the first one that matches
121→        if let matchingAlternativeAlias = alternativeAliases.filter({ $0.range(of: serverName) != nil }).first {
122→            return matchingAlternativeAlias
123→        }
124→        
125→        guard useFallback else {
126→            return nil
127→        }
128→        
129→        // Or just return the canonical alias if any
130→        if let canonicalAlias {
131→            return canonicalAlias
132→        }
133→        
134→        // And finally return whatever the first alternative alias is
135→        return alternativeAliases.first
136→    }
137→}
